st.sidebar.caption(f"Recorded sampling frequency: {fs:g} samples/second")
st.sidebar.caption(f"Channel names in WFDB header: {', '.join(signal_names)}")

c1, c2, c3 = st.sidebar.columns(3)
if c1.button("▶ Start", use_container_width=True):
    if st.session_state.row_cursor >= len(record_rows):
        reset_playback()
    st.session_state.playing = True
if c2.button("⏸ Stop", use_container_width=True):
    st.session_state.playing = False
if c3.button("↺ Reset", use_container_width=True):
    reset_playback()

if st.sidebar.button("Clear prediction history", use_container_width=True):
    st.session_state.history = []
    st.session_state.current_result = None

# ------------------------- LIVE REPLAY LOOP -------------------------

@st.fragment(run_every="250ms")
def live_monitor():
    rows = record_rows
    rid = st.session_state.record_id
    ch = selected_channel

    # Pull a short packet of actual samples on each fragment rerun.
    if st.session_state.playing:
        if st.session_state.row_cursor >= len(rows):
            st.session_state.playing = False
        else:
            row = rows.iloc[st.session_state.row_cursor]
            start_s = float(row["window_start_s"])
            end_s = float(row["window_end_s"])
            start_sample = int(round(start_s * fs))
            end_sample = int(round(end_s * fs))

            channel_index = next(
                i for i, name in enumerate(signal_names)
                if str(name).strip().casefold() == ch.strip().casefold()
            )
            if start_sample < 0 or end_sample > raw_signal.shape[0] or end_sample <= start_sample:
                st.session_state.last_error = (
                    f"Window sample range [{start_sample}, {end_sample}) "
                    f"is outside record length {raw_signal.shape[0]}."
                )
                st.session_state.playing = False
            else:
                # Cursor is local to the current feature window.
                local_pos = int(st.session_state.sample_cursor)
                packet_n = max(1, int(round(fs * CHUNK_SECONDS * speed)))
                packet_end = min(local_pos + packet_n, end_sample - start_sample)

                if packet_end > local_pos:
                    packet = raw_signal[
                        start_sample + local_pos:start_sample + packet_end,
                        channel_index
                    ]
                    packet_times = start_s + np.arange(
                        local_pos, packet_end, dtype=float
                    ) / fs
                    st.session_state.trace_time.extend(packet_times.tolist())
                    st.session_state.trace_values.extend(packet.tolist())
                    st.session_state.sample_cursor = packet_end

                # When the exact 20-second recorded segment is complete,
                # predict from its already-prepared 58-feature row.
                if st.session_state.sample_cursor >= (end_sample - start_sample):
                    x = pd.DataFrame(
                        [[pd.to_numeric(row[f], errors="coerce") for f in FEATURE_COLUMNS]],
                        columns=FEATURE_COLUMNS,
                    )
                    pred = model.predict(x)[0]
                    probs = model.predict_proba(x)[0]
                    prob_map = {
                        str(label): float(prob)
                        for label, prob in zip(MODEL_CLASSES, probs)
                    }
                    item = {
                        "segment": int(row["window_index"]),
                        "record_id": rid,
                        "channel": ch,
                        "start_s": start_s,
                        "end_s": end_s,
                        "predicted_class": str(pred),
                        "confidence": float(np.max(probs)),
                        "reference_class": str(row[TARGET_COL]),
                        **{f"prob_{k}": v for k, v in prob_map.items()},
                    }
                    st.session_state.history.append(item)
                    st.session_state.current_result = item
                    st.session_state.row_cursor += 1
                    st.session_state.sample_cursor = 0

                # Keep a rolling display buffer.
                cutoff = (st.session_state.trace_time[-1] - DISPLAY_SECONDS
                          if st.session_state.trace_time else 0)
                while st.session_state.trace_time and st.session_state.trace_time[0] < cutoff:
                    st.session_state.trace_time.pop(0)
                    st.session_state.trace_values.pop(0)

    if st.session_state.last_error:
        st.error(st.session_state.last_error)

    # Header metrics
    completed = len(st.session_state.history)
    total = len(rows)
    current_row = min(st.session_state.row_cursor, total - 1)
    elapsed = 0.0
    if st.session_state.row_cursor < total:
        r = rows.iloc[current_row]
        elapsed = float(r["window_start_s"]) + st.session_state.sample_cursor / fs
    elif total:
        elapsed = float(rows.iloc[-1]["window_end_s"])

    m1, m2, m3, m4 = st.columns(4)
    m1.metric("Patient", f"Patient-{rid}")
    m2.metric("Channel", f"{ch}")
    m3.metric("Playback time", f"{elapsed:.1f} s")
    m4.metric("Sampling rate", f"{fs:g} Hz")

    st.progress(min(completed / max(total, 1), 1.0))

    st.subheader("Continuous recorded ECG trace")

    # Persistent Plotly chart: create the figure once per Streamlit session,
    # then update its trace data and rolling axes on each fragment rerun.
    if "ecg_plotly_fig" not in st.session_state:
        initial_fig = go.Figure()
        initial_fig.add_trace(go.Scattergl(
            x=[],
            y=[],
            mode="lines",
            name="ECG",
            line={"width": 1.25, "color": "#16a34a"},
            hovertemplate="Time: %{x:.3f} s<br>ECG: %{y:.4f} mV<extra></extra>",
        ))
        initial_fig.update_layout(
            height=320,
            margin={"l": 55, "r": 20, "t": 15, "b": 45},
            showlegend=False,
            uirevision="ecg-live-stable-view",
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(0,0,0,0)",
            xaxis={
                "title": "Time in original MIT-BIH record (seconds)",
                "fixedrange": True,
                "showgrid": True,
            },
            yaxis={
                "title": "ECG amplitude (mV)",
                "fixedrange": True,
                "showgrid": True,
            },
        )
        st.session_state.ecg_plotly_fig = initial_fig

    ecg_fig = st.session_state.ecg_plotly_fig

    if st.session_state.trace_time:
        x_values = st.session_state.trace_time
        y_values = st.session_state.trace_values
        x_right = float(x_values[-1])
        x_left = max(0.0, x_right - DISPLAY_SECONDS)
        y_array = np.asarray(y_values, dtype=float)
        finite_y = y_array[np.isfinite(y_array)]

        if finite_y.size:
            y_min = float(finite_y.min())
            y_max = float(finite_y.max())
            y_pad = max((y_max - y_min) * 0.08, 0.05)
        else:
            y_min, y_max, y_pad = -1.0, 1.0, 0.0

        # Mutate the retained figure rather than constructing a new Figure
        # and Scattergl trace on every refresh.
        ecg_fig.data[0].x = x_values
        ecg_fig.data[0].y = y_values
        ecg_fig.update_xaxes(range=[x_left, max(x_right, x_left + 0.1)])
        ecg_fig.update_yaxes(range=[y_min - y_pad, y_max + y_pad])

        st.plotly_chart(
            ecg_fig,
            use_container_width=True,
            key="ecg_live_plot_persistent",
            config={"displayModeBar": False, "scrollZoom": False},
        )
    else:
        ecg_fig.data[0].x = []
        ecg_fig.data[0].y = []
        st.info("Press Start to begin sample-by-sample replay of the selected recorded ECG.")

    result = st.session_state.current_result
    st.subheader("Latest 20-second screening prediction")
    if result:
        a, b, c = st.columns(3)
        a.metric("Predicted class", result["predicted_class"])
        b.metric("Model confidence", f'{result["confidence"] * 100:.1f}%')
        c.metric("Segment", f'{result["start_s"]:.0f}–{result["end_s"]:.0f} s')
        st.caption(
            f'Reference dataset label (display only): {result["reference_class"]}. '
            "This reference label is not supplied to the model."
        )
        prob_cols = st.columns(5)
        for col, label in zip(prob_cols, CLASS_ORDER):
            with col:
                st.write(f"**{label}**")
                st.progress(result.get(f"prob_{label}", 0.0))
                st.caption(f'{result.get(f"prob_{label}", 0.0) * 100:.1f}%')
    else:
        st.info("The model will issue its first prediction after the first complete 20-second segment.")

    st.subheader("Prediction history")
    if st.session_state.history:
        hist = pd.DataFrame(st.session_state.history)
        view = hist[[
            "segment", "record_id", "channel", "start_s", "end_s",
            "predicted_class", "confidence"
        ]].copy()
        # Presentation-only patient label. Keep hist["record_id"] numeric/string
        # MIT-BIH IDs unchanged for matching, prediction, and CSV export.
        view.insert(
            1,
            "patient",
            view["record_id"].map(lambda record_id: f"Patient-{record_id}"),
        )
        view = view.drop(columns=["record_id"])
        view["confidence"] = (view["confidence"] * 100).round(2).astype(str) + "%"
        st.dataframe(view.iloc[::-1], use_container_width=True, hide_index=True)
        st.download_button(
            "Download prediction history (CSV)",
            data=hist.to_csv(index=False).encode("utf-8"),
            file_name=f"mitbih_{rid}_{ch}_phase1_predictions.csv",
            mime="text/csv",
        )
    else:
        st.caption("No completed windows yet.")

live_monitor()
